import numpy as np


class MixedFeasibilityJDEDense:
    """
    Mixed-integer constrained optimiser: jDE differential evolution with
    current-to-pbest/1 and rand/1 mixing on a unified [0,1) encoding.
    Selection follows Deb's feasibility rules.

    Feasibility boosting:
      * when an infeasible trial is produced and a feasible incumbent exists,
        the trial is pulled toward the incumbent by line-search repair
        (alpha = 0.5, then 0.25); the first feasible repair replaces the trial,
      * a decoded-point cache so duplicate designs never consume budget,
      * a crossover-density floor and elite-centred restarts.
    """

    def __init__(self, budget=10000, dim=10):
        self.budget = int(budget)
        self.dim = int(dim)

    def __call__(self, func):
        rng = np.random.default_rng()
        d = self.dim

        lb = np.asarray(func.bounds.lb, dtype=float).reshape(-1)[:d]
        ub = np.asarray(func.bounds.ub, dtype=float).reshape(-1)[:d]
        vt = [str(t) for t in func.variable_types][:d]

        n = np.ones(d)
        for i, t in enumerate(vt):
            if t != "continuous":
                n[i] = float(func.n_values[i])

        cont = np.array([t == "continuous" for t in vt])
        cat = np.where(np.array([t == "categorical" for t in vt]))[0]
        scale = np.where(cont, ub - lb, 1.0)
        lo = np.where(cont, lb, 0.0)

        state = {"evals": 0, "best_key": (np.inf, np.inf), "best_u": None, "best_x": None}
        cache = {}

        def decode(u):
            return np.where(cont, lo + u * scale, np.minimum(np.floor(u * n), n - 1))

        def evaluate(u):
            x = decode(u)
            ck = tuple(np.round(x, 10).tolist())
            if ck in cache:
                key = cache[ck]
            else:
                if state["evals"] >= self.budget:
                    raise RuntimeError("budget")
                f, g = func(x)
                state["evals"] += 1
                f = float(f)
                if np.isnan(f):
                    f = np.inf
                g = np.nan_to_num(np.asarray(g, dtype=float).ravel(), nan=1e10, posinf=1e10)
                viol = float(np.sum(np.maximum(g, 0.0)))
                if viol > 0.0:
                    key = (viol, np.inf)
                elif not np.isfinite(f):
                    key = (1e10, np.inf)
                else:
                    key = (0.0, f)
                cache[ck] = key
            if key < state["best_key"]:
                state["best_key"] = key
                state["best_u"] = np.array(u, copy=True)
                state["best_x"] = np.array(x, copy=True)
            return key

        def random_u(k):
            return rng.random((k, d))

        def reset_categorical(trial):
            for j in cat:
                if rng.random() < 1.0 / d:
                    k = int(n[j])
                    trial[j] = (rng.integers(k) + rng.random()) / k
            return trial

        def can_eval():
            return state["evals"] < self.budget

        def feasible_incumbent():
            return state["best_key"][0] == 0.0 and state["best_u"] is not None

        def repair(trial, key):
            """Pull an infeasible trial toward the best feasible point (line search)."""
            if key[0] == 0.0 or not feasible_incumbent():
                return trial, key
            anchor = state["best_u"]
            for a in (0.5, 0.25):
                if not can_eval():
                    break
                cand = np.clip(anchor + a * (trial - anchor), 0.0, 1.0 - 1e-12)
                ck = evaluate(cand)
                if ck[0] == 0.0:
                    return cand, ck
            return trial, key

        NP = int(min(max(20, 5 * d), max(6, self.budget // 10)))
        pop = random_u(NP)
        keys = [(np.inf, np.inf)] * NP
        for i in range(NP):
            if not can_eval():
                break
            keys[i] = evaluate(pop[i])
        if state["best_u"] is None:
            return state["best_key"][1], state["best_x"]

        Fs = np.full(NP, 0.5)
        CRs = np.full(NP, 0.9)
        CR_MIN = 0.25
        REPAIR_P = 0.5
        stagnation = 0
        gen_best = state["best_key"]

        while can_eval():
            order = sorted(range(NP), key=lambda j: keys[j])
            n_top = max(2, int(0.15 * NP))
            top = order[:n_top]

            for i in range(NP):
                if not can_eval():
                    break
                Fi = rng.uniform(0.1, 1.0) if rng.random() < 0.1 else Fs[i]
                CRi = rng.uniform(CR_MIN, 1.0) if rng.random() < 0.1 else max(CRs[i], CR_MIN)

                others = np.delete(np.arange(NP), i)
                r = rng.choice(others, 2, replace=False)
                pb = top[rng.integers(n_top)]

                if rng.random() < 0.6:
                    mutant = pop[i] + Fi * (pop[pb] - pop[i]) + Fi * (pop[r[0]] - pop[r[1]])
                else:
                    r3 = rng.choice(others, 3, replace=False)
                    mutant = pop[r3[0]] + Fi * (pop[r3[1]] - pop[r3[2]])

                mask = rng.random(d) < CRi
                mask[rng.integers(d)] = True
                trial = np.where(mask, mutant, pop[i])
                trial = reset_categorical(trial)
                trial = np.clip(trial, 0.0, 1.0 - 1e-12)

                if not can_eval():
                    break
                k = evaluate(trial)

                # feasibility-boosting repair of infeasible trials
                if k[0] > 0.0 and feasible_incumbent() and rng.random() < REPAIR_P:
                    trial, k = repair(trial, k)

                if k <= keys[i]:
                    pop[i] = trial
                    keys[i] = k
                    Fs[i] = Fi
                    CRs[i] = CRi

            if state["best_key"] < gen_best:
                gen_best = state["best_key"]
                stagnation = 0
            else:
                stagnation += 1

            if stagnation >= 20 and can_eval():
                stagnation = 0
                order = sorted(range(NP), key=lambda j: keys[j])
                elite = order[0]
                best_u = state["best_u"]
                n_re = NP // 2
                for idx, j in enumerate(order[NP - n_re:]):
                    if not can_eval():
                        break
                    if j == elite:
                        continue
                    if idx % 2 == 0:
                        cand = best_u + rng.normal(0.0, 0.1, d)
                        pop[j] = np.clip(cand, 0.0, 1.0 - 1e-12)
                    else:
                        pop[j] = random_u(1)[0]
                    keys[j] = evaluate(pop[j])
                    Fs[j] = 0.5
                    CRs[j] = 0.9
                gen_best = state["best_key"]

        return state["best_key"][1], state["best_x"]
